<script setup lang="ts">
import {ref,computed,watch,onMounted,onBeforeUnmount} from 'vue';import {api,ApiError} from '../api';import {useWorkspace,type WorkTab} from '../stores';import Modal from '../components/Modal.vue';import {workTypes,importanceLabels,assignmentLabels,workFields,currentAssignments} from '../department-work';
const props=defineProps<{tab:WorkTab}>(),work=useWorkspace();const departmentId=props.tab.payload?.departmentId;
const form=ref<any>({title:'',category_id:null,category_name:'',work_type:'fixed',importance:'normal',status:'active',...Object.fromEntries(Object.keys(workFields).map(k=>[k,''])),assignments:[]});
const review=ref(false),latestForm=ref<any>(null);
const catalog=ref<any>(null),people=ref<any[]>([]),search=ref(''),error=ref(''),message=ref(''),loading=ref(false),conflict=ref(false),confirm=ref(false),version=ref('');let baseline='',pendingKey='',requestId='',resolveConfirm:((ok:boolean)=>void)|null=null;
const selectedItem=computed(()=>catalog.value?.items.find((i:any)=>i.id===props.tab.recordId));const permitted=computed(()=>Boolean(catalog.value?.canManage));
const filteredPeople=computed(()=>people.value.filter(p=>[p.full_name,p.email,p.employee_code,p.job_title].some(v=>String(v||'').toLowerCase().includes(search.value.trim().toLowerCase()))));
watch(form,()=>{if(baseline)props.tab.dirty=JSON.stringify(form.value)!==baseline;message.value='';},{deep:true,flush:'sync'});
function fromItem(i:any){return {title:i.title,category_id:i.category_id,category_name:'',work_type:i.work_type,importance:i.importance,status:i.status,...Object.fromEntries(Object.keys(workFields).map(k=>[k,i[k]||''])),assignments:currentAssignments(i).map((a:any)=>({user_id:a.user_id,assignment_type:a.assignment_type}))};}
const fieldLabels:Record<string,string>={title:'工作名稱',category_id:'工作分類',category_name:'新增分類',work_type:'工作性質',importance:'重要程度',status:'狀態',...workFields,assignments:'人員分工'};
const differences=computed(()=>latestForm.value?Object.keys(fieldLabels).filter(key=>JSON.stringify(form.value[key])!==JSON.stringify(latestForm.value[key])):[]);
function display(value:any,key:string){if(key==='assignments')return value.map((a:any)=>name(a.user_id)+' · '+assignmentLabels[a.assignment_type]).join('、')||'未指派';if(key==='category_id')return catalog.value?.categories.find((c:any)=>c.id===value)?.name||'新增分類';if(key==='status')return value==='active'?'啟用':'停用';return workTypes[value]||importanceLabels[value]||value||'未填寫';}
function useLatest(key:string){form.value[key]=JSON.parse(JSON.stringify(latestForm.value[key]));}
async function load(preserve=false){loading.value=true;error.value='';message.value='';try{if(!departmentId)throw Error('缺少部門資料，請由部門工作頁重新開啟');const d=await api('department-work?department='+departmentId);catalog.value=d;version.value=d.version;if(props.tab.recordId&&!selectedItem.value)throw Error('此工作職掌已不存在');if(d.canManage)people.value=(await api('department-work?people=true')).people;
 const remote=selectedItem.value?fromItem(selectedItem.value):null;
 if(preserve&&remote){const remoteState=JSON.stringify(remote);review.value=remoteState!==baseline;latestForm.value=remote;baseline=remoteState;props.tab.dirty=JSON.stringify(form.value)!==baseline;}
 else if(!preserve){if(remote)form.value=remote;baseline=JSON.stringify(form.value);props.tab.dirty=false;review.value=false;latestForm.value=null;}
 conflict.value=false;
 }catch(e){error.value=(e as Error).message;conflict.value=true;}finally{loading.value=false;}}

function toggle(id:string,role:string){const index=form.value.assignments.findIndex((a:any)=>a.user_id===id&&a.assignment_type===role);if(index>=0)form.value.assignments.splice(index,1);else form.value.assignments.push({user_id:id,assignment_type:role});}
function name(id:string){const p=people.value.find(p=>p.id===id)||selectedItem.value?.assignments.find((a:any)=>a.user_id===id)?.user;return p?`${p.employee_code||''} ${p.full_name||p.email}`:id;}
function answer(ok:boolean){confirm.value=false;resolveConfirm?.(ok);resolveConfirm=null;}
async function save(){if(!permitted.value||loading.value||props.tab.busy||conflict.value||review.value||confirm.value)return false;error.value='';if(!form.value.title.trim()||(!form.value.category_id&&!form.value.category_name.trim())){error.value='請填寫工作名稱，並選擇或新增分類';return false;}
 if(!await new Promise<boolean>(r=>{resolveConfirm=r;confirm.value=true;}))return false;
 props.tab.busy=true;const data={...form.value,id:props.tab.recordId||null,organization_unit_id:departmentId};const key=JSON.stringify(data);if(key!==pendingKey){pendingKey=key;requestId=crypto.randomUUID();}
 try{const result=await api('department-work',{method:'POST',body:JSON.stringify({data,requestId,expected:version.value})});props.tab.recordId=result.id;props.tab.title='職掌 · '+form.value.title;baseline=JSON.stringify(form.value);props.tab.dirty=false;pendingKey='';requestId='';work.departmentRevision++;await load();message.value=error.value?'已儲存，請重新載入確認最新資料':'工作職掌已儲存';if(error.value)conflict.value=true;return true;}catch(e){error.value=(e as Error).message;conflict.value=e instanceof ApiError&&e.status===409;return false;}finally{props.tab.busy=false;}}
props.tab.save=save;onMounted(()=>load());onBeforeUnmount(()=>{answer(false);delete props.tab.save;});
</script>
<template><header class="page-heading"><div><p class="eyebrow">部門管理 / {{catalog?.department.name||'工作職掌'}}</p><h1>{{tab.recordId?'工作職掌內容':'新增工作職掌'}}</h1></div><button :disabled="loading||tab.busy||confirm" @click="load(tab.dirty)">{{tab.dirty?'重新載入（保留草稿）':'重新載入'}}</button></header>
<p v-if="error" class="notice error" role="alert">{{error}}</p><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="loading" role="status">載入工作職掌…</p><p v-if="catalog&&!permitted" class="notice">目前為唯讀，或部門已停用。</p>
<section v-if="review" class="conflict-review" aria-label="核對最新職掌"><h2>核對最新資料與草稿</h2><p>其他操作已修改此職掌。草稿仍保留，請逐項核對後再儲存。</p><p v-if="!differences.length">草稿已與目前資料相同。</p><div v-for="key in differences" :key="key" class="difference"><h3>{{fieldLabels[key]}}</h3><div class="comparison"><div><strong>目前資料</strong><p>{{display(latestForm[key],key)}}</p></div><div><strong>你的草稿</strong><p>{{display(form[key],key)}}</p></div></div><button type="button" @click="useLatest(key)">採用目前的{{fieldLabels[key]}}</button></div><button class="primary" :disabled="loading||tab.busy" @click="review=false">已核對，繼續編輯</button></section><form v-if="catalog" @submit.prevent="save"><fieldset :disabled="!permitted||loading||tab.busy||conflict||review||confirm"><div class="work-form"><label class="wide">工作名稱<input v-model="form.title" required maxlength="300"></label><label>工作分類<select aria-label="工作分類" v-model="form.category_id"><option :value="null">新增分類</option><option v-for="c in catalog.categories.filter((c:any)=>c.status==='active'||c.id===form.category_id)" :value="c.id">{{c.name}}{{c.status==='inactive'?'（停用）':''}}</option></select></label><label v-if="!form.category_id">新分類名稱<input v-model="form.category_name" required maxlength="200"></label><label>工作性質<select aria-label="工作性質" v-model="form.work_type"><option v-for="(label,key) in workTypes" :value="key">{{label}}</option></select></label><label>重要程度<select aria-label="重要程度" v-model="form.importance"><option v-for="(label,key) in importanceLabels" :value="key">{{label}}</option></select></label><label>狀態<select aria-label="職掌狀態" v-model="form.status"><option value="active">啟用</option><option value="inactive">停用</option></select></label><label v-for="(label,key) in workFields" :key="key" class="wide">{{label}}<textarea v-model="form[key]" rows="3" maxlength="10000"/></label></div>
<section><h2>人員分工（{{form.assignments.length}} 項指派）</h2><p v-if="!form.assignments.length">尚未指派人員</p><div v-for="a in form.assignments" :key="a.user_id+a.assignment_type" class="selected-person"><span>{{name(a.user_id)}} · {{assignmentLabels[a.assignment_type]}}</span><button type="button" @click="toggle(a.user_id,a.assignment_type)">移除</button></div><template v-if="permitted"><label class="search">搜尋指派人員<input v-model="search" placeholder="姓名、代碼、職稱或 Email"></label><div class="people"><div v-for="p in filteredPeople" :key="p.id" class="person"><span>{{p.employee_code}} {{p.full_name||p.email}}<small>{{p.job_title}}</small></span><label v-for="(label,key) in assignmentLabels" class="check"><input type="checkbox" :checked="form.assignments.some((a:any)=>a.user_id===p.id&&a.assignment_type===key)" @change="toggle(p.id,key)">{{label}}</label></div></div><p v-if="!filteredPeople.length">找不到符合的人員</p></template></section></fieldset><div class="dialog-actions"><button v-if="permitted" class="primary" :disabled="!tab.dirty||loading||tab.busy||conflict||review||confirm">{{tab.busy?'儲存中…':'儲存工作職掌'}}</button></div></form>
<section v-if="selectedItem"><h2>人員指派歷史</h2><p v-if="!selectedItem.assignments.length">尚無指派歷史</p><ul><li v-for="a in selectedItem.assignments" :key="a.id">{{a.user?.full_name||a.user?.email}} · {{assignmentLabels[a.assignment_type]}} · {{a.effective_from}} ～ {{a.effective_to||'目前'}}（{{a.status==='active'&&!a.effective_to?'現任':'已結束'}}）</li></ul></section>
<Modal v-if="confirm" title="確認儲存工作職掌" @cancel="answer(false)"><p>{{catalog.department.name}} / {{form.title}}</p><p>將儲存工作內容與 {{form.assignments.length}} 項人員指派；異動保留歷史。{{form.status==='inactive'?'此職掌將設為停用。':''}}</p><div class="dialog-actions"><button @click="answer(false)">返回編輯</button><button class="primary" @click="answer(true)">確認儲存</button></div></Modal>
</template>
<style scoped>.conflict-review{border-block:2px solid var(--primary);padding:16px 0;margin:24px 0}.difference{border-bottom:1px solid var(--line);padding:16px 0;margin-bottom:16px}.comparison{display:grid;grid-template-columns:1fr 1fr;gap:20px}.comparison p{white-space:pre-wrap;overflow-wrap:anywhere}.difference h3{font-size:16px}@media(max-width:650px){.comparison{grid-template-columns:1fr}}fieldset{border:0;padding:0;min-width:0}.work-form{display:grid;grid-template-columns:1fr 1fr;gap:18px;max-width:1000px}label{display:grid;gap:8px}.wide{grid-column:1/-1}input,select,textarea{width:100%;min-width:0}h2{font-size:18px;margin-top:32px}.selected-person{display:flex;justify-content:space-between;gap:12px;max-width:700px;padding:8px 0}.search{max-width:600px;margin:20px 0}.people{max-height:400px;overflow:auto;border-block:1px solid var(--line)}.person{display:grid;grid-template-columns:minmax(180px,1fr) repeat(3,90px);gap:12px;padding:12px;border-bottom:1px solid var(--line);align-items:center}.check{display:flex;align-items:center}.check input{width:18px;height:18px;min-width:18px;min-height:18px}small{display:block;color:var(--muted)}li{padding:8px 0;overflow-wrap:anywhere}@media(max-width:650px){.work-form{grid-template-columns:1fr}.person{grid-template-columns:repeat(3,1fr)}.person>span{grid-column:1/-1}}</style>
